  deep: [
    { q: "Dlaczego badanie Watsona jest dziś nie do powtórzenia?",
      a: "Wywołano strach u niemowlęcia i nie usunięto go, bo Albert opuścił szpital przed odwarunkowaniem. Hock: dziś żadna komisja etyczna by na to nie pozwoliła; Watson nie był sadystą, ale granice etyczne były wtedy nowe. Krytycy (Harris 1979, Samelson 1980) podważali też, czy reakcje były trwałe i silne.",
      link: "Wróć do mapy przedmiotu: etyka psychologa obejmuje każde badanie." },
    { q: "Skoro gołębie są przesądne, czy przesądy to „głupota”?",
      a: "Nie. Skinner pokazał, że przesąd powstaje z prostego mechanizmu: przypadkowego wzmocnienia. Hock dodaje, że przesądy dają poczucie kontroli w trudnych sytuacjach, zmniejszają lęk i mogą poprawiać wykonanie. Częściej mają je ludzie w niebezpiecznych zawodach.",
      link: "Porównaj z Rogersem: behawioryści nie uwzględniali wewnętrznych znaczeń, humaniści właśnie od nich zaczynali." },
    { q: "Czy agresji uczymy się z ekranu?",
      a: "Bandura (1963): model filmowy i rysunkowy też zwiększał agresję dzieci, choć słabiej niż żywy. Dlatego jego prace przywoływano na przesłuchaniach w Kongresie USA o przemocy w telewizji. Funk i in. (1999): oceny przemocy w grach są subiektywne, zwłaszcza przy przemocy „rysunkowej”.",
      link: "Optymistycznie: Johnson i Johnson (1996) – dobry model (mediator) też jest naśladowany." },
    { q: "Pawłow, Watson, Skinner i Bandura: co ich łączy, a co różni?",
      a: "Pawłow i Watson: związek między bodźcami (warunkowanie klasyczne). Skinner: związek zachowania z konsekwencjami (instrumentalne). Bandura idzie dalej: uczymy się, patrząc na innych, bez własnych konsekwencji, a wiedza nie musi od razu przejść w działanie. To już krok w stronę procesów poznawczych, czyli tematu zajęć 3.",
      link: "Na zajęciach 3 Tolman pokaże, że nawet szczury uczą się „w głowie”." }
  ],

  talk: [
    { q: "Wyjaśnij warunkowanie klasyczne na przykładzie badań Pawłowa (pojęcia UCS, UCR, CS, CR).",
      a: "<p>Bodziec neutralny kojarzy się z bodźcem wywołującym odruch i zaczyna sam go wywoływać. Pokarm (<b>UCS</b>) wywołuje ślinienie (<b>UCR</b>). Metronom (na początku neutralny) wielokrotnie poprzedza pokarm i staje się <b>CS</b>; sam wywołuje ślinienie (<b>CR</b>). Bodziec neutralny musi być przed bezwarunkowym: wanilia po kwasie nie dała efektu nawet po 427 próbach.</p>",
      keys: ["bodziec neutralny", "UCS–UCR", "CS–CR", "metronom", "kolejność bodźców"], src: "Slajdy 8–9, Hock s. 93–98" },
    { q: "Na czym polegało badanie Małego Alberta i co pokazało? Jakie ma problemy etyczne?",
      a: "<p>Watson i Rayner (1920) łączyli białego szczura (wcześniej neutralny) z głośnym hukiem (UCS). Po 7 próbach Albert bał się szczura. Strach <b>generalizował</b> się na królika, psa, futro, maskę Mikołaja i utrzymywał się po miesiącu. Pokazali, że emocje można warunkować (przeciw Freudowi). Problemy: wywołano strach u niemowlęcia i go nie usunięto; wątpliwości co do trwałości reakcji.</p>",
      keys: ["szczur + huk", "generalizacja", "emocje wyuczone", "przeciw Freudowi", "brak odwarunkowania"], src: "Hock s. 101–107" },
    { q: "Wyjaśnij cztery rodzaje konsekwencji w warunkowaniu instrumentalnym. Podaj przykłady.",
      a: "<p>Wzmocnienie zwiększa częstość zachowania, kara ją zmniejsza; pozytywne = dodanie, negatywne = odebranie. <b>Wzmocnienie +</b>: pochwała za oddanie pracy. <b>Wzmocnienie −</b>: zapinasz pas, ustaje pisk. <b>Kara +</b>: mandat za szybką jazdę. <b>Kara −</b>: utrata dostępu do czatu za obrażanie innych. O nazwie decyduje efekt.</p>",
      keys: ["częściej / rzadziej", "dodanie / odebranie", "4 przykłady", "decyduje efekt"], src: "Slajdy 13–16" },
    { q: "Jak Skinner wytłumaczył przesądy? Opisz badanie z gołębiami.",
      a: "<p>8 głodnych gołębi w skrzynce Skinnera dostawało pokarm co 15 sekund, niezależnie od zachowania. U 6 utrwaliły się dziwne ruchy (obroty, głowa w rogu, kołysanie), bo przypadkiem poprzedzały pokarm: <b>wzmocnienie przypadkowe</b>. Zachowanie wzmacniane rzadko jest odporne na wygaszanie („tańczący” gołąb: ponad 10 000 reakcji). Tak samo powstają przesądy u ludzi (kręglarz, sportowcy).</p>",
      keys: ["pokarm co 15 s", "wzmocnienie przypadkowe", "6 z 8", "odporność na wygaszanie", "przesądy u ludzi"], src: "Hock s. 108–115" },
    { q: "Czym jest modelowanie? Opisz badanie z lalką Bobo i jego wyniki.",
      a: "<p>Modelowanie to uczenie się przez obserwację innych i skutków ich zachowań (Bandura). W badaniu z 1961 roku dzieci widziały dorosłego, który bił lalkę Bobo, albo spokojnie się bawił; grupa kontrolna nie widziała nikogo. Po łagodnej frustracji dzieci z agresywnym modelem dokładnie naśladowały agresję, choć model wyszedł. Potwierdzono 3 z 4 hipotez: chłopcy bardziej agresywni fizycznie, dziewczynki słownie; męski model silniejszy.</p>",
      keys: ["obserwacja", "model agresywny / nieagresywny", "naśladowanie bez modela", "płeć", "3 z 4 hipotez"], src: "Slajdy 18–20, Hock s. 116–124" },
    { q: "Czym różni się warunkowanie klasyczne od instrumentalnego? Podaj po przykładzie.",
      a: "<p><b>Klasyczne</b>: uczymy się związku <b>między bodźcami</b>, a reakcja jest automatyczna (dźwięk telefonu kojarzony z trudnymi rozmowami wywołuje napięcie). <b>Instrumentalne</b>: uczymy się związku <b>zachowania z konsekwencją</b> (odbierasz telefon, rozmowa z bliską osobą jest miła, więc chętniej odbierasz).</p>",
      keys: ["bodziec → reakcja", "zachowanie → konsekwencja", "przykład telefonu"], src: "Slajd 17" },
    { q: "Dlaczego uczenie się nie jest tym samym co zmiana zachowania?",
      a: "<p>Uczenie się to nieobserwowalny proces; zmiana zachowania może być jego przejawem, ale nie musi. Możemy nauczyć się przez obserwację bez naśladowania, a wyuczona umiejętność może ujawnić się dopiero w odpowiedniej sytuacji, zależnie od motywacji (Bandura: wyuczenie ≠ wykonanie; Tolman: uczenie się utajone).</p>",
      keys: ["nieobserwowalny proces", "obserwacja bez naśladowania", "ujawnienie później", "motywacja"], src: "Slajdy 5–6" }
  ],

